I'll create API Gateway configurations for Inventory Management System.

## Kong Configuration (kong.yml)

```yaml
_format_version: "3.0"

services:
  - name: product-service
    url: http://product-service:8000
    routes:
      - name: product-service-route
        paths:
          - /api/v1/products
        strip_path: false
    plugins:
      - name: rate-limiting
        config:
          minute: 100
          policy: local
      - name: jwt
      - name: correlation-id
        config:
          header_name: X-Request-ID
          generator: uuid

  - name: warehouse-service
    url: http://warehouse-service:8000
    routes:
      - name: warehouse-service-route
        paths:
          - /api/v1/warehouses
    plugins:
      - name: rate-limiting
        config:
          minute: 200

  - name: order-service
    url: http://order-service:8000
    routes:
      - name: order-service-route
        paths:
          - /api/v1/orders

consumers:
  - username: api-user
    jwt_secrets:
      - key: api-key
        secret: your-secret-key

plugins:
  - name: prometheus
  - name: cors
    config:
      origins:
        - "*"
      methods:
        - GET
        - POST
        - PUT
        - DELETE
      headers:
        - Authorization
        - Content-Type
```

## Nginx Configuration (nginx.conf)

```nginx
upstream product_service {
    least_conn;
    server product-service:8000 weight=5;
    server product-service-2:8000 weight=5;
    keepalive 32;
}

upstream warehouse_service {
    least_conn;
    server warehouse-service:8000;
    keepalive 32;
}

upstream order_service {
    server order-service:8000;
}

# Rate limiting
limit_req_zone $binary_remote_addr zone=api_limit:10m rate=100r/s;

server {
    listen 80;
    server_name api.inventory.com;

    # Health check
    location /health {
        return 200 'OK';
    }

    # product-service routes
    location /api/v1/products {
        limit_req zone=api_limit burst=50 nodelay;

        proxy_pass http://product_service;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Request-ID $request_id;

        # Timeouts
        proxy_connect_timeout 5s;
        proxy_read_timeout 30s;

        # Circuit breaker
        proxy_next_upstream error timeout http_500 http_502 http_503;
        proxy_next_upstream_tries 3;
    }

    # warehouse-service routes
    location /api/v1/warehouses {
        proxy_pass http://warehouse_service;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
    }

    # order-service routes
    location /api/v1/orders {
        proxy_pass http://order_service;
        proxy_set_header Host $host;
    }

    # Error pages
    error_page 502 503 504 /50x.html;
    location = /50x.html {
        return 503 '{"error": "Service temporarily unavailable"}';
        add_header Content-Type application/json;
    }
}
```

