I'll create a gRPC service for product-service.

## product_service.proto

```protobuf
syntax = "proto3";

package ecommerce.product_service;

service ProductService {
    rpc CreateProduct(CreateProductRequest) returns (CreateProductResponse);
    rpc GetProduct(GetProductRequest) returns (GetProductResponse);
    rpc ListProducts(ListProductsRequest) returns (ListProductsResponse);
    rpc UpdateProduct(UpdateProductRequest) returns (UpdateProductResponse);
    rpc DeleteProduct(DeleteProductRequest) returns (DeleteProductResponse);
    rpc WatchProducts(Empty) returns (stream ProductEvent);
}

message Product {
    string id = 1;
    string name = 2;
    string status = 3;
    int64 created_at = 4;
}

message CreateProductRequest {
    string name = 1;
}

message CreateProductResponse {
    Product product = 1;
}

message GetProductRequest {
    string id = 1;
}

message GetProductResponse {
    Product product = 1;
}

message ListProductsRequest {
    int32 page = 1;
    int32 page_size = 2;
}

message ListProductsResponse {
    repeated Product products = 1;
    int32 total = 2;
}

message UpdateProductRequest {
    string id = 1;
    string name = 2;
    string status = 3;
}

message UpdateProductResponse {
    Product product = 1;
}

message DeleteProductRequest {
    string id = 1;
}

message DeleteProductResponse {
    bool success = 1;
}

message ProductEvent {
    string event_type = 1;
    Product product = 2;
}

message Empty {}
```

## server.py

```python
import grpc
from concurrent import futures
import product_service_pb2 as pb2
import product_service_pb2_grpc as pb2_grpc

class ProductServicer(pb2_grpc.ProductServiceServicer):
    def __init__(self):
        self.db = {}

    def CreateProduct(self, request, context):
        import uuid
        id = str(uuid.uuid4())
        product = pb2.Product(
            id=id,
            name=request.name,
            status="active",
            created_at=int(time.time())
        )
        self.db[id] = product
        return pb2.CreateProductResponse(product=product)

    def GetProduct(self, request, context):
        product = self.db.get(request.id)
        if not product:
            context.set_code(grpc.StatusCode.NOT_FOUND)
            return pb2.GetProductResponse()
        return pb2.GetProductResponse(product=product)

    def ListProducts(self, request, context):
        items = list(self.db.values())
        start = (request.page - 1) * request.page_size
        end = start + request.page_size
        return pb2.ListProductsResponse(
            products=items[start:end],
            total=len(items)
        )

def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    pb2_grpc.add_ProductServiceServicer_to_server(ProductServicer(), server)
    server.add_insecure_port('[::]:50051')
    server.start()
    server.wait_for_termination()

if __name__ == '__main__':
    serve()
```

## client.py

```python
import grpc
import product_service_pb2 as pb2
import product_service_pb2_grpc as pb2_grpc

class ProductClient:
    def __init__(self, host='localhost', port=50051):
        self.channel = grpc.insecure_channel(f'{host}:{port}')
        self.stub = pb2_grpc.ProductServiceStub(self.channel)

    def create(self, name: str):
        response = self.stub.CreateProduct(pb2.CreateProductRequest(name=name))
        return response.product

    def get(self, id: str):
        response = self.stub.GetProduct(pb2.GetProductRequest(id=id))
        return response.product

    def list(self, page=1, page_size=10):
        response = self.stub.ListProducts(pb2.ListProductsRequest(page=page, page_size=page_size))
        return response.products
```

