import grpc
from concurrent import futures
import customer_service_pb2 as pb2
import customer_service_pb2_grpc as pb2_grpc

class CustomerServicer(pb2_grpc.CustomerServiceServicer):
    def __init__(self):
        self.db = {}

    def CreateCustomer(self, request, context):
        import uuid
        id = str(uuid.uuid4())
        customer = pb2.Customer(
            id=id,
            name=request.name,
            status="active",
            created_at=int(time.time())
        )
        self.db[id] = customer
        return pb2.CreateCustomerResponse(customer=customer)

    def GetCustomer(self, request, context):
        customer = self.db.get(request.id)
        if not customer:
            context.set_code(grpc.StatusCode.NOT_FOUND)
            return pb2.GetCustomerResponse()
        return pb2.GetCustomerResponse(customer=customer)

    def ListCustomers(self, request, context):
        items = list(self.db.values())
        start = (request.page - 1) * request.page_size
        end = start + request.page_size
        return pb2.ListCustomersResponse(
            customers=items[start:end],
            total=len(items)
        )

def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    pb2_grpc.add_CustomerServiceServicer_to_server(CustomerServicer(), server)
    server.add_insecure_port('[::]:50051')
    server.start()
    server.wait_for_termination()

if __name__ == '__main__':
    serve()
```

