## Nginx Configuration (nginx.conf)

```nginx
upstream account_service {
    least_conn;
    server account-service:8000 weight=5;
    server account-service-2:8000 weight=5;
    keepalive 32;
}

upstream transaction_service {
    least_conn;
    server transaction-service:8000;
    keepalive 32;
}

upstream payment_service {
    server payment-service:8000;
}

# Rate limiting
limit_req_zone $binary_remote_addr zone=api_limit:10m rate=100r/s;

server {
    listen 80;
    server_name api.fintech.com;

    # Health check
    location /health {
        return 200 'OK';
    }

    # account-service routes
    location /api/v1/accounts {
        limit_req zone=api_limit burst=50 nodelay;

        proxy_pass http://account_service;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Request-ID $request_id;

        # Timeouts
        proxy_connect_timeout 5s;
        proxy_read_timeout 30s;

        # Circuit breaker
        proxy_next_upstream error timeout http_500 http_502 http_503;
        proxy_next_upstream_tries 3;
    }

    # transaction-service routes
    location /api/v1/transactions {
        proxy_pass http://transaction_service;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
    }

    # payment-service routes
    location /api/v1/payments {
        proxy_pass http://payment_service;
        proxy_set_header Host $host;
    }

    # Error pages
    error_page 502 503 504 /50x.html;
    location = /50x.html {
        return 503 '{"error": "Service temporarily unavailable"}';
        add_header Content-Type application/json;
    }
}
```

