## server.py

```python
import grpc
from concurrent import futures
import patient_service_pb2 as pb2
import patient_service_pb2_grpc as pb2_grpc

class PatientServicer(pb2_grpc.PatientServiceServicer):
    def __init__(self):
        self.db = {}

    def CreatePatient(self, request, context):
        import uuid
        id = str(uuid.uuid4())
        patient = pb2.Patient(
            id=id,
            name=request.name,
            status="active",
            created_at=int(time.time())
        )
        self.db[id] = patient
        return pb2.CreatePatientResponse(patient=patient)

    def GetPatient(self, request, context):
        patient = self.db.get(request.id)
        if not patient:
            context.set_code(grpc.StatusCode.NOT_FOUND)
            return pb2.GetPatientResponse()
        return pb2.GetPatientResponse(patient=patient)

    def ListPatients(self, request, context):
        items = list(self.db.values())
        start = (request.page - 1) * request.page_size
        end = start + request.page_size
        return pb2.ListPatientsResponse(
            patients=items[start:end],
            total=len(items)
        )

def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    pb2_grpc.add_PatientServiceServicer_to_server(PatientServicer(), server)
    server.add_insecure_port('[::]:50051')
    server.start()
    server.wait_for_termination()

if __name__ == '__main__':
    serve()
```

