```nginx
upstream user_service {
    least_conn;
    server user-service:8000 weight=5;
    server user-service-2:8000 weight=5;
    keepalive 32;
}

upstream flight_service {
    least_conn;
    server flight-service:8000;
    keepalive 32;
}

upstream hotel_service {
    server hotel-service:8000;
}

# Rate limiting
limit_req_zone $binary_remote_addr zone=api_limit:10m rate=100r/s;

server {
    listen 80;
    server_name api.travel.com;

    # Health check
    location /health {
        return 200 'OK';
    }

    # user-service routes
    location /api/v1/users {
        limit_req zone=api_limit burst=50 nodelay;

        proxy_pass http://user_service;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Request-ID $request_id;

        # Timeouts
        proxy_connect_timeout 5s;
        proxy_read_timeout 30s;

        # Circuit breaker
        proxy_next_upstream error timeout http_500 http_502 http_503;
        proxy_next_upstream_tries 3;
    }

    # flight-service routes
    location /api/v1/flights {
        proxy_pass http://flight_service;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
    }

    # hotel-service routes
    location /api/v1/hotels {
        proxy_pass http://hotel_service;
        proxy_set_header Host $host;
    }

    # Error pages
    error_page 502 503 504 /50x.html;
    location = /50x.html {
        return 503 '{"error": "Service temporarily unavailable"}';
        add_header Content-Type application/json;
    }
}
