## server.py

```python
import grpc
from concurrent import futures
import employee_service_pb2 as pb2
import employee_service_pb2_grpc as pb2_grpc

class EmployeeServicer(pb2_grpc.EmployeeServiceServicer):
    def __init__(self):
        self.db = {}

    def CreateEmployee(self, request, context):
        import uuid
        id = str(uuid.uuid4())
        employee = pb2.Employee(
            id=id,
            name=request.name,
            status="active",
            created_at=int(time.time())
        )
        self.db[id] = employee
        return pb2.CreateEmployeeResponse(employee=employee)

    def GetEmployee(self, request, context):
        employee = self.db.get(request.id)
        if not employee:
            context.set_code(grpc.StatusCode.NOT_FOUND)
            return pb2.GetEmployeeResponse()
        return pb2.GetEmployeeResponse(employee=employee)

    def ListEmployees(self, request, context):
        items = list(self.db.values())
        start = (request.page - 1) * request.page_size
        end = start + request.page_size
        return pb2.ListEmployeesResponse(
            employees=items[start:end],
            total=len(items)
        )

def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    pb2_grpc.add_EmployeeServiceServicer_to_server(EmployeeServicer(), server)
    server.add_insecure_port('[::]:50051')
    server.start()
    server.wait_for_termination()

if __name__ == '__main__':
    serve()
```

