    rpc CreateUser(CreateUserRequest) returns (CreateUserResponse);
    rpc GetUser(GetUserRequest) returns (GetUserResponse);
    rpc ListUsers(ListUsersRequest) returns (ListUsersResponse);
    rpc UpdateUser(UpdateUserRequest) returns (UpdateUserResponse);
    rpc DeleteUser(DeleteUserRequest) returns (DeleteUserResponse);
    rpc WatchUsers(Empty) returns (stream UserEvent);
}

message User {
    string id = 1;
    string name = 2;
    string status = 3;
    int64 created_at = 4;
}

message CreateUserRequest {
    string name = 1;
}

message CreateUserResponse {
    User user = 1;
}

message GetUserRequest {
    string id = 1;
}

message GetUserResponse {
    User user = 1;
}

message ListUsersRequest {
    int32 page = 1;
    int32 page_size = 2;
}

message ListUsersResponse {
    repeated User users = 1;
    int32 total = 2;
}

message UpdateUserRequest {
    string id = 1;
    string name = 2;
    string status = 3;
}

message UpdateUserResponse {
    User user = 1;
}

message DeleteUserRequest {
    string id = 1;
}

message DeleteUserResponse {
    bool success = 1;
}

message UserEvent {
    string event_type = 1;
    User user = 2;
}

message Empty {}
```

## server.py

```python
import grpc
from concurrent import futures
import user_service_pb2 as pb2
import user_service_pb2_grpc as pb2_grpc

class UserServicer(pb2_grpc.UserServiceServicer):
    def __init__(self):
        self.db = {}

    def CreateUser(self, request, context):
        import uuid
        id = str(uuid.uuid4())
        user = pb2.User(
            id=id,
            name=request.name,
            status="active",
            created_at=int(time.time())
        )
        self.db[id] = user
        return pb2.CreateUserResponse(user=user)

    def GetUser(self, request, context):
        user = self.db.get(request.id)
        if not user:
            context.set_code(grpc.StatusCode.NOT_FOUND)
            return pb2.GetUserResponse()
        return pb2.GetUserResponse(user=user)

    def ListUsers(self, request, context):
        items = list(self.db.values())
        start = (request.page - 1) * request.page_size
        end = start + request.page_size
        return pb2.ListUsersResponse(
            users=items[start:end],
            total=len(items)
        )

def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    pb2_grpc.add_UserServiceServicer_to_server(UserServicer(), server)
    server.add_insecure_port('[::]:50051')
    server.start()
    server.wait_for_termination()

if __name__ == '__main__':
    serve()
```

## client.py

```python
import grpc
import user_service_pb2 as pb2
import user_service_pb2_grpc as pb2_grpc

class UserClient:
    def __init__(self, host='localhost', port=50051):
        self.channel = grpc.insecure_channel(f'{host}:{port}')
        self.stub = pb2_grpc.UserServiceStub(self.channel)

    def create(self, name: str):
        response = self.stub.CreateUser(pb2.CreateUserRequest(name=name))
        return response.user

    def get(self, id: str):
        response = self.stub.GetUser(pb2.GetUserRequest(id=id))
        return response.user

    def list(self, page=1, page_size=10):
        response = self.stub.ListUsers(pb2.ListUsersRequest(page=page, page_size=page_size))
        return response.users
